export function parseCrosswordLexicon() {
  const out = [];
  const seen = new Set();
  for (const line of CROSSWORD_LEXICON_LINES.split('\n')) {
    const t = line.trim();
    if (!t) continue;
    const pipe = t.indexOf('|');
    if (pipe < 1) continue;
    const wordRaw = t.slice(0, pipe).trim();
    const clue = t.slice(pipe + 1).trim();
    const w = wordRaw
      .toUpperCase()
      .replace(/Ё/g, 'Е')
      .replace(/[^А-ЯA-Z0-9]/g, '');
    if (w.length < 2 || w.length > 14 || !clue) continue;
    if (seen.has(w)) continue;
    seen.add(w);
    out.push({ word: w, clue });
  }
  return out;
}
